1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the new owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>}: the
11	 * upper-cased first three letters of the last name, a hyphen, and a global 4-digit
12	 * zero-padded sequence equal to one more than the current number of owners (e.g.
13	 * {@code SMI-0007}). Runs after {@link BuildOwner} (so the entity and its last name
14	 * exist) and before {@link SaveOwner} persists the code.
15	 */
16	public class AssignOwnerCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        int sequence = ownerRepository.findAll().size() + 1;
20	        owner.setCustomerCode(format(owner.getLastName(), sequence));
21	    }
22	
23	    private static String format(String lastName, int sequence) {
24	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
25	        return String.format("%s-%04d", prefix, sequence);
26	    }
27	}
