35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "membership_number")
67	    private String membershipNumber;
68	
69	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
70	    private Set<Pet> pets;
71	
72	    public String getAddress() {
73	        return this.address;
74	    }
75	
76	    public void setAddress(String address) {
77	        this.address = address;
78	    }
79	
80	    public String getCity() {
81	        return this.city;
82	    }
83	
84	    public void setCity(String city) {
85	        this.city = city;
86	    }
87	
88	    public String getTelephone() {
89	        return this.telephone;
90	    }
91	
92	    public void setTelephone(String telephone) {
93	        this.telephone = telephone;
94	    }
95	
96	    public String getEmail() {
97	        return this.email;
98	    }
99	
100	    public void setEmail(String email) {
101	        this.email = email;
102	    }
103	
104	    public LocalDate getRegistrationDate() {
105	        return this.registrationDate;
106	    }
107	
108	    public void setRegistrationDate(LocalDate registrationDate) {
109	        this.registrationDate = registrationDate;
110	    }
111	
112	    public String getCustomerCode() {
113	        return this.customerCode;
114	    }
115	
116	    public void setCustomerCode(String customerCode) {
117	        this.customerCode = customerCode;
118	    }
119	
120	    public String getHouseholdId() {
121	        return this.householdId;
122	    }
123	
124	    public void setHouseholdId(String householdId) {
125	        this.householdId = householdId;
126	    }
127	
128	    public Integer getNamesakeCount() {
129	        return this.namesakeCount;
130	    }
131	
132	    public void setNamesakeCount(Integer namesakeCount) {
133	        this.namesakeCount = namesakeCount;
134	    }
135	
136	    public String getMembershipNumber() {
137	        return this.membershipNumber;
138	    }
139	
140	    public void setMembershipNumber(String membershipNumber) {
141	        this.membershipNumber = membershipNumber;
142	    }
143	
144	    /**
145	     * The owner's membership tier: {@code SILVER} when this owner had no namesakes at
146	     * creation ({@code namesakeCount} is 0) and has an email address, {@code BRONZE}
147	     * otherwise. Derived from stored state, never persisted.
148	     */
149	    public String getMembershipTier() {
150	        boolean silver = Integer.valueOf(0).equals(this.namesakeCount)
151	            && this.email != null && !this.email.isEmpty();
152	        return silver ? "SILVER" : "BRONZE";
153	    }
154	
155	    protected Set<Pet> getPetsInternal() {
156	        if (this.pets == null) {
157	            this.pets = new HashSet<>();
158	        }
159	        return this.pets;
160	    }
161	
162	    protected void setPetsInternal(Set<Pet> pets) {
163	        this.pets = pets;
164	    }
165	
166	    public List<Pet> getPets() {
167	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
168	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
169	        return Collections.unmodifiableList(sortedPets);
170	    }
171	
172	    public void setPets(List<Pet> pets) {
173	        this.pets = new HashSet<>(pets);
174	    }
175	
176	    public void addPet(Pet pet) {
177	        getPetsInternal().add(pet);
178	        pet.setOwner(this);
179	    }
180	
181	    /**
182	     * Return the Pet with the given name, or null if none found for this Owner.
183	     *
184	     * @param name to test
185	     * @return true if pet name is already in use
186	     */
187	    public Pet getPet(String name) {
188	        return getPet(name, false);
189	    }
190	
191	    /**
192	     * Return the Pet with the given name, or null if none found for this Owner.
193	     *
194	     * @param name to test
195	     * @return true if pet name is already in use
196	     */
197	    public Pet getPet(String name, boolean ignoreNew) {
198	        name = name.toLowerCase();
199	        for (Pet pet : getPetsInternal()) {
200	            if (!ignoreNew || !pet.isNew()) {
201	                String compName = pet.getName();
202	                compName = compName.toLowerCase();
203	                if (compName.equals(name)) {
204	                    return pet;
205	                }
206	            }
207	        }
208	        return null;
209	    }
210	
211	    public Pet getPet(Integer petId) {
212	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
213	    }
214	
215	    @Override
216	    public String toString() {
217	        return new ToStringCreator(this)
218	
219	            .append("id", this.getId())
220	            .append("new", this.isNew())
221	            .append("lastName", this.getLastName())
222	            .append("firstName", this.getFirstName())
223	            .append("address", this.address)
224	            .append("city", this.city)
225	            .append("telephone", this.telephone)
226	            .toString();
227	    }
228	}
