package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the new owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>}: the
 * upper-cased first three letters of the last name, a hyphen, and a global 4-digit
 * zero-padded sequence equal to one more than the current number of owners (e.g.
 * {@code SMI-0007}). Runs after {@link BuildOwner} (so the entity and its last name
 * exist) and before {@link SaveOwner} persists the code.
 */
public class AssignOwnerCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int sequence = ownerRepository.findAll().size() + 1;
        owner.setCustomerCode(format(owner.getLastName(), sequence));
    }

    private static String format(String lastName, int sequence) {
        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
        return String.format("%s-%04d", prefix, sequence);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the new owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}:
 * the upper-cased first three letters of the city, a hyphen, the upper-cased first three
 * letters of the last name, a hyphen, and a per-city 4-digit zero-padded sequence equal to
 * one more than the number of owners already in that city (e.g. {@code FRA-SMI-0007}). Runs
 * after {@link BuildOwner} (so the entity, its city and last name exist) and before
 * {@link SaveOwner} persists the code.
 */
public class AssignOwnerCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int sequence = countOwnersInCity(ownerRepository, owner.getCity()) + 1;
        owner.setCustomerCode(String.format("%s-%s-%04d",
                prefix(owner.getCity()), prefix(owner.getLastName()), sequence));
    }

    private static long countOwnersInCity(OwnerRepository ownerRepository, String city) {
        return ownerRepository.findAll().stream()
                .filter(existing -> city.equals(existing.getCity()))
                .count();
    }

    private static String prefix(String value) {
        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
    }
}

